def numTilePossibilities(tiles: str) -> int:
    from collections import Counter
    counts = Counter(tiles)
    def backtrack():
        total = 0
        for ch in counts:
            if counts[ch] > 0:
                counts[ch] -= 1
                total += 1 + backtrack()
                counts[ch] += 1
        return total
    return backtrack()

